action.mutation:
mutation UpdateAssetGroup($payload: [AssetGroupUpdatePayloadInput!]!) {
  mutation: updateAssetGroup(payload: $payload) { 
    id
    name
  }
}

mutation UpdateAsset($payload: [AssetUpdatePayloadInput!]!) {
  mutation: updateAsset(payload: $payload) { 
    id
    number
  }
}

mutation CreateAssetGroup($payload: [AssetGroupCreatePayloadInput!]!) {
  mutation: createAssetGroup(payload: $payload) { 
    id
    name
  }
}
